import{_ as e,o as a,c as s,ae as n}from"./chunks/framework.B2ul6ABY.js";const h=JSON.parse('{"title":"What Is MapleSpike?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-maplespike.md","filePath":"guide/what-is-maplespike.md"}'),r={name:"guide/what-is-maplespike.md"};function i(o,t,d,l,c,p){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="what-is-maplespike" tabindex="-1">What Is MapleSpike? <a class="header-anchor" href="#what-is-maplespike" aria-label="Permalink to &quot;What Is MapleSpike?&quot;">​</a></h1><p>MapleSpike is <strong>Canada&#39;s sovereign, AI-native government data pipeline</strong>. It ingests, verifies, curates, and surfaces Canadian government data through a unified REST API, MCP server, and TypeScript SDK.</p><p>One API key grants access to every major Canadian government dataset — Statistics Canada cubes, open.canada.ca CKAN portals, provincial data, parliamentary committees, federal lobbying, procurement, court decisions, immigration data, and more — packaged with machine-readable citations, provenance metadata, and trust scores.</p><h2 id="mission" tabindex="-1">Mission <a class="header-anchor" href="#mission" aria-label="Permalink to &quot;Mission&quot;">​</a></h2><p>Canada&#39;s open data ecosystem is fragmented. Developers and journalists navigate 6+ separate portals (StatCan WDS, open.canada.ca CKAN, ON/BC/AB/QC portals), each with different APIs, rate limits, data formats, and licensing. MapleSpike fills this gap with a single pipeline.</p><blockquote><p><strong>One pipeline to ingest, verify, and serve all Canadian public data.</strong></p></blockquote><h2 id="data-sources" tabindex="-1">Data Sources <a class="header-anchor" href="#data-sources" aria-label="Permalink to &quot;Data Sources&quot;">​</a></h2><p>MapleSpike ingests from <strong>65+ data modules</strong> covering every major category of Canadian government information:</p><table tabindex="0"><thead><tr><th>Category</th><th>Modules</th></tr></thead><tbody><tr><td>Government Core</td><td>RSS feeds, gov API (StatCan/CKAN), attestation (citations), provincial CKAN, GC standards</td></tr><tr><td>Parliamentary</td><td>Committees, GIC appointments, Canada Gazette, Elections Canada</td></tr><tr><td>Oversight</td><td>OAG, PBO, Ethics Commissioner, Competition Bureau, CRTC, federal tribunals, ATI</td></tr><tr><td>Legal</td><td>CanLII court decisions, LMIA, legislation tracking, A2J legal API, CIPO</td></tr><tr><td>Immigration</td><td>IRCC permanent/temporary residents, IRB refugee decisions, CBSA enforcement</td></tr><tr><td>Indigenous</td><td>CIRNAC land claims, ISC programs, FN transparency, TRC Calls to Action</td></tr><tr><td>Defence</td><td>DND personnel/procurement, Veterans Affairs benefits/services</td></tr><tr><td>Transport</td><td>TSB occurrences, Transport Canada recalls, CTA rulings, Infrastructure Canada</td></tr><tr><td>Health</td><td>Health Canada drug/device approvals, CIHI, CADTH, CFIA recalls, PMPRB, PHAC</td></tr><tr><td>Corporate</td><td>Lobbying registry, procurement, SEDI insider trading, SEDAR+ filings, CRA charities</td></tr><tr><td>Influence</td><td>30+ tracked IOs/NGOs/think tanks, NGO RSS feeds, cross-reference engine</td></tr><tr><td>Media</td><td>CRTC decisions, broadcasting ownership, cultural spending</td></tr><tr><td>Environment</td><td>NPRI pollutant releases, Species at Risk, Impact Assessment, fisheries, agriculture, LODE geospatial</td></tr><tr><td>Provincial</td><td>All 13 provinces/territories — CKAN portals, legislatures, lobbying, regulators</td></tr><tr><td>Municipal</td><td>19 major cities, plus long-tail federation covering 3,490+ municipalities</td></tr><tr><td>Social</td><td>CPP/OAS, EI, Canada Child Benefit, poverty stats, social assistance</td></tr><tr><td>Science</td><td>CSA space missions, Mitacs grants, ocean observations, polar data</td></tr><tr><td>Economy</td><td>Bank of Canada, CMHC housing data, trade indicators</td></tr></tbody></table><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GitHub Pages (maplespike.ca)</span></span>
<span class="line"><span>  └── Portal (static HTML/CSS/JS — landing, dashboard, docs)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>K3s Cluster (nexus)</span></span>
<span class="line"><span>  ├── MCP server (SSE, port 3001) ── 22 tools, all live</span></span>
<span class="line"><span>  ├── API server (REST, Bearer auth, rate limits)</span></span>
<span class="line"><span>  │     ├── SQLite (keys, usage, audit)</span></span>
<span class="line"><span>  │     ├── In-memory cache (node-cache)</span></span>
<span class="line"><span>  │     └── pipeline-core (ingestion, curation, verification)</span></span>
<span class="line"><span>  └── Engine CronJobs (ingestion scheduling)</span></span></code></pre></div><h2 id="access-methods" tabindex="-1">Access Methods <a class="header-anchor" href="#access-methods" aria-label="Permalink to &quot;Access Methods&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Description</th><th>Best For</th></tr></thead><tbody><tr><td><strong>MCP Server</strong></td><td>22 tools for AI agents via Model Context Protocol</td><td>AI assistants (Claude Desktop, Cursor)</td></tr><tr><td><strong>REST API</strong></td><td>HTTP endpoints at <code>/v1/*</code> with Bearer auth</td><td>Scripts, apps, direct integration</td></tr><tr><td><strong>TypeScript SDK</strong></td><td><code>@maplespike/sdk</code> — typed client for all modules</td><td>Node.js/TypeScript projects</td></tr><tr><td><strong>CLI</strong></td><td>Run the MCP server locally via stdio</td><td>Local development</td></tr></tbody></table><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><ul><li><strong>65 ingestion modules</strong> — ~113K lines of TypeScript</li><li><strong>22 MCP tools</strong> — all live and returning real data</li><li><strong>All 13 provinces/territories</strong> — full oversight coverage (273 regulators, 21 categories)</li><li><strong>1,141+ unique external endpoints</strong> consumed across all modules</li><li><strong>19 cities</strong> with direct open data fetchers; <strong>3,490+</strong> via federation</li><li><strong>10 packages</strong> — compile clean with full CI/CD pipeline</li></ul><h2 id="attribution" tabindex="-1">Attribution <a class="header-anchor" href="#attribution" aria-label="Permalink to &quot;Attribution&quot;">​</a></h2><p>All data sourced from Canadian government portals is provided under the <strong>Open Government Licence – Canada</strong>. Every API response includes the required attribution:</p><blockquote><p><em>&quot;Contains information licensed under the Open Government Licence – Canada.&quot;</em></p></blockquote>`,18)])])}const g=e(r,[["render",i]]);export{h as __pageData,g as default};
